-- 041 — the catalogue entries and values for 040's sources.
--
-- Separate from 040 because Postgres will not let a transaction use an enum label that the
-- same transaction added, and the migration runner sends each file as one transaction. The
-- `development` and `tourism` categories are therefore declared there and used here.
--
-- Every figure below was checked against a total the report states for itself. The tourism
-- capacity columns sum to 7,622 units and 188,999 beds; the pilgrim arrivals to 3,477,957
-- for 2019. The composite index has no published column total to check against, so all
-- thirteen districts were transcribed for all six years and the ranks verified to run 1-10
-- within each year -- a mistyped rank would break that and a mistyped score would not, which
-- is why the rank column is the one worth checking.

ON CONFLICT (indicator_key) DO UPDATE SET
  category         = EXCLUDED.category,
  scope            = EXCLUDED.scope,
  label_en         = EXCLUDED.label_en,
  label_hi         = EXCLUDED.label_hi,
  unit             = EXCLUDED.unit,
  decimals         = EXCLUDED.decimals,
  higher_is_better = EXCLUDED.higher_is_better;

ON CONFLICT (indicator_key, area_id, vintage) DO UPDATE SET
  value      = EXCLUDED.value,
  source_id  = EXCLUDED.source_id,
  fetched_at = EXCLUDED.fetched_at;

